import {exportAlbum,readAlbum,verifyAlbumImages} from './snapshot-files.js?v=architecture-collection-43';
import {frameSnapshot} from './snapshot-frame.js?v=architecture-collection-43';
import {listSnapshots,addSnapshot,importSnapshots,captionSnapshot,deleteSnapshot,captureSnapshot} from './snapshots.js?v=architecture-collection-43';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let photoURL;
export async function showSnapshots(ui,selectedId=null,album=null){const {city,renderer,dialog,notify}=ui,$=s=>document.querySelector(s);try{const photos=await listSnapshots(),albums=[...new Set(photos.map(p=>p.city))].sort();album=album??city().name;const items=photos.filter(p=>p.city===album).sort((a,b)=>a.created-b.created||a.id-b.id),photo=items.find(p=>p.id===selectedId)||items.at(-1),index=photo?items.indexOf(photo):-1;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=photo?URL.createObjectURL(photo.blob):null;const url=photoURL;
 dialog('City snapshots',`${photo?'':'<p>Frame your city with pan, zoom and rotation. Photos stay in this browser, separately from city-file exports.</p>'}<details ${photo?'':'open'}><summary>Capture current city view</summary><div class="actions snapshot-capture"><label>Image size<select id="snapshotSize"><option value="640">Small · 640 px</option><option value="1024" selected>Medium · 1024 px</option><option value="1600">Large · 1600 px</option></select></label><button id="takeSnapshot" class="primary">Capture ${esc(city().name)}</button><button id="frameSnapshot">Frame on map</button></div></details><label>Photo album<select id="photoAlbum">${[...new Set([album,...albums])].map(name=>`<option ${name===album?'selected':''}>${esc(name)}</option>`).join('')}</select></label>${photo?`<img id="cityPhoto" class="city-photo" src="${url}" alt="${esc(photo.caption||photo.city+' city snapshot')}"><p><strong>${esc(photo.city)}</strong> · Mayor ${esc(photo.mayor)} · ${photo.startYear+Math.floor(photo.month/12)} / ${photo.month%12+1}<br>${photo.population.toLocaleString()} residents · §${photo.funds.toLocaleString()} · ${photo.width} × ${photo.height}</p><div class="actions"><button id="previousPhoto" ${index===0?'disabled':''}>← Previous</button><span>${index+1} / ${items.length}</span><button id="nextPhoto" ${index===items.length-1?'disabled':''}>Next →</button><button id="enlargePhoto">Enlarge</button><a class="photo-download" href="${url}" download="sims3000-${photo.id}.png">Download PNG</a></div><label>Caption<textarea id="photoCaption" maxlength="500" rows="3">${esc(photo.caption)}</textarea></label><div class="actions"><button id="saveCaption" class="primary">Save caption</button><button id="deletePhoto">Delete this photo</button></div>`:'<p>No snapshots in this album yet. Capture a view to begin.</p>'}<details><summary>Share or restore an album</summary><p>Export the selected album with captions and city details. Importing adds copies without replacing existing photos. These album files are separate from playable city saves.</p><button id="exportAlbum" ${items.length?'':'disabled'}>Export selected album</button><label>SIMS3000 album file<input id="albumFile" type="file" accept=".json,application/json"></label><button id="importAlbum">Import album file</button></details><p class="fine">${photos.length} / 50 photos in this browser. Clearing site data deletes local albums; download photos you want to keep.</p>`);
 $('#dialog')?.addEventListener('close',()=>{if(url)URL.revokeObjectURL(url);},{once:true});const guard=fn=>async()=>{try{await fn();}catch(e){notify(e.message);}};
 $('#takeSnapshot').onclick=guard(async()=>{const button=$('#takeSnapshot');button.disabled=true;try{const p=await captureSnapshot(renderer,city(),Number($('#snapshotSize').value)),id=await addSnapshot(p);await showSnapshots(ui,id,p.city);notify('Snapshot saved to this browser.');}finally{if(button.isConnected)button.disabled=false;}});
 $('#frameSnapshot').onclick=()=>{const size=Number($('#snapshotSize').value);$('#dialog').close();frameSnapshot(renderer,async crop=>{try{if(crop){const p=await captureSnapshot(renderer,city(),size,crop),id=await addSnapshot(p);await showSnapshots(ui,id,p.city);notify('Framed snapshot saved.');}else await showSnapshots(ui,selectedId,album);}catch(e){notify(e.message);await showSnapshots(ui,selectedId,album);}});};
 $('#exportAlbum').onclick=guard(async()=>{const file=await exportAlbum(items),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download='sims3000-photo-album.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 $('#importAlbum').onclick=guard(async()=>{const file=$('#albumFile').files[0];if(!file)throw Error('Choose an album file first.');const button=$('#importAlbum');button.disabled=true;try{const imported=await readAlbum(file);await verifyAlbumImages(imported);const id=await importSnapshots(imported);await showSnapshots(ui,id,imported.at(-1).city);notify(`${imported.length} photos imported.`);}finally{if(button.isConnected)button.disabled=false;}});
 $('#photoAlbum').onchange=()=>showSnapshots(ui,null,$('#photoAlbum').value);
 if(photo){$('#previousPhoto').onclick=()=>showSnapshots(ui,items[index-1].id,album);$('#nextPhoto').onclick=()=>showSnapshots(ui,items[index+1].id,album);$('#enlargePhoto').onclick=()=>{$('#cityPhoto').classList.toggle('enlarged');$('#enlargePhoto').textContent=$('#cityPhoto').classList.contains('enlarged')?'Fit photo':'Enlarge';};$('#saveCaption').onclick=guard(async()=>{await captionSnapshot(photo.id,$('#photoCaption').value);notify('Caption saved.');});$('#deletePhoto').onclick=guard(async()=>{await deleteSnapshot(photo.id);await showSnapshots(ui,null,album);notify('Snapshot deleted.');});}
 }catch(e){notify(e.message);}}
